import { Capacitor } from '@capacitor/core';
import { Geolocation } from '@capacitor/geolocation';

const reverseGeocode = async (latitude, longitude) => {
  try {
    const url = new URL('https://geocoding-api.open-meteo.com/v1/reverse');
    url.searchParams.set('latitude', String(latitude));
    url.searchParams.set('longitude', String(longitude));
    url.searchParams.set('language', 'en');
    url.searchParams.set('format', 'json');
    const resp = await fetch(url.toString());
    if (!resp.ok) return null;
    const data = await resp.json();
    const row = (data.results && data.results[0]) || data;
    if (!row || (!row.name && !row.admin1)) return null;
    const parts = [row.name, row.admin1, row.country_code || row.country].filter(Boolean);
    return parts.join(', ');
  } catch (err) {
    console.warn('Reverse geocode failed', err);
    return null;
  }
};

const readBrowserPosition = () =>
  new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      reject(new Error('Geolocation is not available in this browser'));
      return;
    }
    navigator.geolocation.getCurrentPosition(resolve, reject, {
      enableHighAccuracy: false,
      timeout: 12000,
      maximumAge: 5 * 60 * 1000,
    });
  });

/**
 * Ask the device/browser for the current GPS position.
 * Returns { latitude, longitude, location_name, fromDevice: true } or null.
 */
export async function getDeviceLocation() {
  try {
    let latitude;
    let longitude;

    if (Capacitor.isNativePlatform()) {
      const permission = await Geolocation.requestPermissions();
      const granted =
        permission.location === 'granted' || permission.coarseLocation === 'granted';
      if (!granted) {
        return null;
      }
      const position = await Geolocation.getCurrentPosition({
        enableHighAccuracy: false,
        timeout: 12000,
        maximumAge: 5 * 60 * 1000,
      });
      latitude = position.coords.latitude;
      longitude = position.coords.longitude;
    } else {
      const position = await readBrowserPosition();
      latitude = position.coords.latitude;
      longitude = position.coords.longitude;
    }

    const location_name =
      (await reverseGeocode(latitude, longitude)) || 'Current location';

    return {
      latitude,
      longitude,
      location_name,
      fromDevice: true,
    };
  } catch (err) {
    console.warn('Device location unavailable', err);
    return null;
  }
}
